-- =============================================================================
-- Carga del Analisis de riesgo de FINANZAS (Supervisor de finanzas), tomado de su formato en Excel.
-- Lo deja a nombre del usuario con puesto "Supervisor de finanzas" (si hay varios, el que se llame Nancy).
-- Si ya se habia cargado, lo ACTUALIZA (mismo folio). Despues se edita normal desde el portal.
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run.
-- =============================================================================
do $carga$
declare v_id uuid; v_ar uuid;
begin
  select id into v_id from public.profiles
   where rol = 'supervisor_finanzas' and activo
   order by (nombre ilike '%nancy%') desc, created_at limit 1;
